def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    # Check if the command is valid
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not isinstance(varargs, Sequence):
        raise TypeError("varargs must be a sequence")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an integer")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an integer")

    # Check if the command is executable
    if not shutil.which(cmd[0]):
        raise FileNotFoundError(f"{cmd[0]} is not executable")

    # Check if the varargs are valid
    for arg in varargs:
        if not isinstance(arg, str):
            raise TypeError(f"{arg} must be a string")

    # Check if the target_concurrency is valid
    if target_concurrency < 1:
        raise ValueError("target_concurrency must be greater than or equal to 1")

    # Check if the _max_length is valid
    if _max_length < 1:
        raise ValueError("_max_length must be greater than or equal to 1")

    # Create a list of partitions
    partitions = []
    for i in range(target_concurrency):
        partitions.append([])

    # Add the varargs to the partitions
    for arg in varargs:
        partitions[i % target_concurrency].append(arg)

    # Create a list of processes
    processes = []
    for partition in partitions:
        processes.append(subprocess.Popen(cmd + partition, stdout=subprocess.PIPE, stderr=subprocess.PIPE))

    # Wait for all processes to finish
    for process in processes:
        process.wait()

    # Read the output from all processes
    output = b""
    for process in processes:
        output += process.stdout.read()

    # Return the output and the exit code
    return (processes[0].returncode, output)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        raise ValueError("Invalid version string")
    return tuple(int(x) for x in s.split("."))

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if len(cmd) == 0:
        return cmd
    if os.name == "nt":
        # Fix for https://bugs.python.org/issue8557
        if cmd[0].startswith("#!"):
            cmd = cmd[1:]
        # Make deep-path shebangs work
        if cmd[0].startswith("\\"):
            cmd = cmd[1:]
    return cmd

def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    if key in cache:
                        return cache[key]
                    else:
                        result = func(*args, **kwargs)
                        cache[key] = result
                        return result
            else:
                if key in cache:
                    return cache[key]
                else:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0
        lock = threading.Lock()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            with lock:
                now = timer()
                try:
                    value, expire_at = cache[key]
                    if now < expire_at:
                        hits += 1
                        return value
                    else:
                        misses += 1
                        raise KeyError
                except KeyError:
                    misses += 1
                    value = func(*args, **kwargs)
                    cache[key] = (value, now + ttl)
                    return value

        def cache_info():
            with lock:
                return {
                    "hits": hits,
                    "misses": misses,
                    "maxsize": maxsize,
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        mru = []
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                mru.remove(key)
                mru.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                mru.append(key)
                if len(mru) > maxsize:
                    cache.pop(mru.pop(0))
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0
        full = False

        def wrapper(*args, **kwargs):
            nonlocal hits, misses, full
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                hits += 1
                return cache[key]
            misses += 1
            if full:
                cache.popitem(last=False)
            cache[key] = result = func(*args, **kwargs)
            full = len(cache) >= maxsize
            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freqs = {}
        hits = misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                hits += 1
                return cache[key]
            misses += 1
            result = func(*args, **kwargs)
            cache[key] = result
            freqs[key] = freqs.get(key, 0) + 1
            if len(cache) > maxsize:
                for key, freq in sorted(freqs.items(), key=lambda x: x[1]):
                    if freq == min(freqs.values()):
                        del cache[key]
                        del freqs[key]
                        break
            return result

        wrapper.cache_info = lambda: (len(cache), hits, misses)
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper

    return decorator

def popitem(self):
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    else:
        key = next(iter(self))
        value = self[key]
        del self[key]
        return (key, value)

def setdefault(self, key, default=None):
