def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    names = []
    descriptions = []
    for name, description in self.__dict__.items():
        if all or name.startswith("_"):
            names.append(name)
            descriptions.append(description)
    return names, descriptions

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if all:
        return [attr for attr in self.__dict__ if not attr.startswith("_")]
    else:
        return [attr for attr in self.__dict__ if not attr.startswith("_") and not callable(getattr(self, attr))]

def _normalizeargs(sequence, output=None):
    if output is None:
        output = []

    for arg in sequence:
        if isinstance(arg, Declaration):
            output.append(arg)
        elif isinstance(arg, tuple):
            output.extend(arg)
        elif isinstance(arg, Interface):
            output.append(arg)
        elif isinstance(arg, ImplementsSpec):
            output.append(arg)
        else:
            raise ValueError("Invalid argument type: {}".format(type(arg)))

    return output

