def is_fill_request_seq(seq):
    if not isinstance(seq, (list, tuple)):
        return False
    if len(seq) == 0:
        return False
    if isinstance(seq[0], FillRequest):
        return True
    if any(isinstance(x, FillRequest) for x in seq):
        return True
    return False

