def format(self, sql, params):
    # Check if the input parameters are valid
    if not isinstance(sql, (str, bytes)):
        raise ValueError("Invalid input type for 'sql'. Must be a string or bytes.")
    if not isinstance(params, (dict, list)):
        raise ValueError("Invalid input type for 'params'. Must be a dictionary or list.")

    # Convert the SQL query to use out-style parameters
    formatted_sql = sql.replace("?", "%s")

    # Convert the parameters to a list if they are a dictionary
    if isinstance(params, dict):
        params = list(params.values())

    # Return the formatted SQL query and parameters
    return formatted_sql, params

