def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    if self.version < prior.version:
        raise ValueError("prior version must be less than or equal to current version")
    if self.version == prior.version:
        raise ValueError("prior version must be less than current version")
    if self.inventory != prior.inventory:
        raise ValueError("inventory must be the same for both prior and current versions")
    if self.inventory_type != prior.inventory_type:
        raise ValueError("inventory type must be the same for both prior and current versions")
    if self.inventory_status != prior.inventory_status:
        raise ValueError("inventory status must be the same for both prior and current versions")
    if self.inventory_location != prior.inventory_location:
        raise ValueError("inventory location must be the same for both prior and current versions")
    if self.inventory_quantity != prior.inventory_quantity:
        raise ValueError("inventory quantity must be the same for both prior and current versions")
    if self.inventory_unit_price != prior.inventory_unit_price:
        raise ValueError("inventory unit price must be the same for both prior and current versions")
    if self.inventory_total_value != prior.inventory_total_value:
