def _explore_folder(folder):
    files = os.listdir(folder)
    packages = {}
    for file in files:
        if file.endswith(".xml"):
            package_name = file.split(".")[0]
            if package_name not in packages:
                packages[package_name] = []
            packages[package_name].append(file)
    return packages

