def render(pieces, style):
    if not pieces or not style:
        raise ValueError("Invalid input: pieces and style must be non-empty")

    if style not in ["html", "markdown"]:
        raise ValueError("Invalid style: must be either 'html' or 'markdown'")

    if not isinstance(pieces, list):
        raise TypeError("Invalid input: pieces must be a list")

    if not all(isinstance(piece, str) for piece in pieces):
        raise TypeError("Invalid input: all pieces must be strings")

    if style == "html":
        return render_html(pieces)
    else:
        return render_markdown(pieces)

