def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path.exists():
        return "path does not exist"
    if not path.is_dir():
        return "path is not a directory"
    if not path.joinpath("0=*").exists():
        return "0=* file does not exist"
    if not path.joinpath("0=*").is_file():
        return "0=* is not a file"
    if path.joinpath("0=*").read_text().startswith("OCFL_1.0"):
        return "root"
    if path.joinpath("0=*").read_text().startswith("OCFL_OBJECT_1.0"):
        return "object"
    return "file"

def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node
        if key not in merged_nodes:
            merged_nodes.append((key, value))
        else:
            existing_value = merged_nodes[key]
            if isinstance(value, MappingNode) and isinstance(existing_value, MappingNode):
                merged_nodes[key] = deep_merge_nodes([(key, value), (key, existing_value)])
            else:
                merged_nodes[key] = value
    return merged_nodes

