def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if number == 0:
        return alphabet[0]

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

def _replace_register(flow_params, register_number, register_value):
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise ValueError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise ValueError("register_value must be a string")

    if register_number not in flow_params:
        raise ValueError(f"Register number {register_number} not found in flow_params")

    flow_params[register_number] = register_value

    return flow_params

def subclasses(cls):
    subclasses = []
    for subclass in cls.__subclasses__():
        subclasses.append(subclass)
        subclasses.extend(subclasses(subclass))
    return subclasses

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        return 0
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if not all(char in alphabet for char in string):
        raise ValueError("string contains characters not in alphabet")
    base = len(alphabet)
    result = 0
    for char in string:
        result *= base
        result += alphabet.index(char)
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not name:
        return name
    if name[0] == name[-1] and name.count(name[0]) == 2:
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 'posix' if os.name == 'posix' else 'cmd'
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'cmd'
    else:
        raise ValueError(f'Invalid platform value: {platform}')

    if platform == 'posix':
        return shlex.split(s, posix=True)
    elif platform == 'cmd':
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f'Invalid platform value: {platform}')

def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("Archive path does not exist")
    if not os.path.isfile(archive_path):
        raise ValueError("Archive path is not a file")
    if not os.access(archive_path, os.R_OK):
        raise ValueError("Archive path is not readable")
    if not os.path.exists(tmp_path):
        raise ValueError("Temporary path does not exist")
    if not os.path.isdir(tmp_path):
        raise ValueError("Temporary path is not a directory")
    if not os.access(tmp_path, os.W_OK):
        raise ValueError("Temporary path is not writable")

    # Extract the archive to a temporary directory
    tmp_dir = tempfile.mkdtemp(dir=tmp_path)
    subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_dir])

    # Find the extracted directory
    extracted_dir = None
    for root, dirs, files in os.walk(tmp_dir):
        if "repo" in dirs:
            extracted_dir = os.path.join(root, "repo")
            break
    if not extracted_dir:
        raise ValueError("Could not find extracted directory")

    # Create a file repo url
    repo_url = "file://" + os.path.abspath(extracted_dir)

    return repo_url

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency string")

    number = parts[0]
    unit = parts[1]

    if unit == "weeks":
        return datetime.timedelta(weeks=int(number))
    elif unit == "days":
        return datetime.timedelta(days=int(number))
    elif unit == "hours":
        return datetime.timedelta(hours=int(number))
    elif unit == "minutes":
        return datetime.timedelta(minutes=int(number))
    elif unit == "seconds":
        return datetime.timedelta(seconds=int(number))
    else:
        raise ValueError("Invalid frequency unit")

