def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc
    else:
        for base in bases:
            if hasattr(base, "__metaclass__"):
                return base.__metaclass__
        return type

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    if len(self.cache) == 0:
        raise KeyError("Cache is empty")

    # Find the least frequently used key
    least_frequent_key = None
    least_frequent_value = None
    for key, value in self.cache.items():
        if least_frequent_key is None or value.freq < self.cache[least_frequent_key].freq:
            least_frequent_key = key
            least_frequent_value = value

    # Remove the least frequently used key
    del self.cache[least_frequent_key]

    return (least_frequent_key, least_frequent_value)

def popitem(self):
    if len(self) == 0:
        raise KeyError("Cache is empty")
    else:
        key = self.least_recently_used[0]
        value = self.cache[key]
        del self.cache[key]
        self.least_recently_used.pop(0)
        return (key, value)

def popitem(self):
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key = next(reversed(self))
    value = self.pop(key)
    return (key, value)

def popitem(self):
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self[key]
    del self[key]
    return (key, value)

