def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input
    if not url:
        raise ValueError("url is required")
    if not document_path:
        document_path = "/.well-known/nodeinfo"

    # Build the NodeInfo document
    nodeinfo_document = {
        "links": {
            "nodeinfo": {
                "href": url + document_path,
                "type": "application/json",
            },
        },
    }

    # Return the NodeInfo document
    return nodeinfo_document

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        raise ValueError("Invalid input: document cannot be empty")

    try:
        # Try parsing the document as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If parsing as JSON fails, try parsing as XRD
        try:
            return parse_xrd(document)
        except ValueError:
            raise ValueError("Invalid input: document is not in JSON or XRD format")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        response = requests.get(f"https://{handle}.well-known/webfinger")
        if response.status_code == 200:
            return response.text
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        response = requests.get(f"https://{handle}.diaspora.example.com/webfinger")
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to retrieve webfinger for {handle}")
    except Exception as e:
        raise Exception(f"Failed to retrieve and parse webfinger for {handle}: {e}")

def retrieve_diaspora_host_meta(host):
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta")
        if response.status_code == 200:
            return XRD.from_xml(response.content)
        else:
            raise Exception(f"Failed to retrieve host-meta from {host}")
    except Exception as e:
        raise Exception(f"Failed to retrieve host-meta from {host}: {e}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        response = requests.post(url, data=data, timeout=timeout, method=method, *args, **kwargs)
        return response.status_code, None
    except Exception as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("'dic' must be a dictionary")
    if not isinstance(val, (str, int, float, bool)):
        raise TypeError("'val' must be a string, integer, float, or boolean")
    if not isinstance(key, str):
        raise TypeError("'key' must be a string")
    if not all(isinstance(k, str) for k in keys):
        raise TypeError("'keys' must be a list of strings")

    if not keys:
        dic[key] = val
    else:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, *keys)

